              {isUpdating ? "저장 중..." : "저장"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={syncEditorOpen} onOpenChange={(open) => { if (!open) setSyncEditorOpen(false); }}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>가사 싱크 맞추기</DialogTitle>
            <DialogDescription>
              음원을 재생하면서 가사가 나올 때마다 아래 버튼을 누르세요. 자동으로 타이밍이 기록됩니다.
            </DialogDescription>
          </DialogHeader>
          <LyricsSyncEditor
            audioUrl={resolveStorageUrl(music.filename)}
            plainLyrics={editLyrics.replace(/\[\d{2}:\d{2}(?:\.\d{2,3})?\]/g, "")}
            onSave={(lrc) => {
              setEditLyrics(lrc);
              setSyncEditorOpen(false);
            }}
            onClose={() => setSyncEditorOpen(false)}
          />
        </DialogContent>
      </Dialog>

      <AlertDialog open={deleteOpen} onOpenChange={setDeleteOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>음원 삭제</AlertDialogTitle>
            <AlertDialogDescription>
              "{music.title}" 음원을 삭제하시겠습니까? 이 작업은 되돌릴 수 없습니다.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>취소</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} disabled={isDeleting} className="bg-red-600 hover:bg-red-700" data-testid="button-confirm-delete">
              {isDeleting ? "삭제 중..." : "삭제"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <Dialog open={reportOpen} onOpenChange={(open) => { setReportOpen(open); if (!open) resetReportForm(); }}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>저작권 신고</DialogTitle>
            <DialogDescription>
              "{music.title}" - {music.artist} 음원에 대한 저작권 신고
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>신고 사유</Label>
              <Select value={reportReason} onValueChange={setReportReason}>
                <SelectTrigger data-testid="select-report-reason">
                  <SelectValue placeholder="신고 사유를 선택하세요" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="unauthorized_use">무단 사용 (원작자 허락 없이 업로드)</SelectItem>
                  <SelectItem value="plagiarism">표절 (다른 음원을 도용)</SelectItem>
                  <SelectItem value="false_attribution">허위 아티스트 표기</SelectItem>
                  <SelectItem value="ai_without_credit">AI 생성물 미표기</SelectItem>
                  <SelectItem value="other">기타</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label htmlFor="report-original-artist">원작자 (선택사항)</Label>
              <Input id="report-original-artist" value={reportOriginalArtist} onChange={(e) => setReportOriginalArtist(e.target.value)} placeholder="원래 아티스트 이름" data-testid="input-report-original-artist" />
            </div>
            <div>
              <Label htmlFor="report-original-title">원곡 제목 (선택사항)</Label>
              <Input id="report-original-title" value={reportOriginalTitle} onChange={(e) => setReportOriginalTitle(e.target.value)} placeholder="원래 곡 제목" data-testid="input-report-original-title" />
            </div>
            <div>
              <Label htmlFor="report-details">상세 설명</Label>
              <Textarea id="report-details" value={reportDetails} onChange={(e) => setReportDetails(e.target.value)} placeholder="저작권 침해에 대한 상세 설명을 작성해주세요" rows={4} data-testid="textarea-report-details" />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { setReportOpen(false); resetReportForm(); }}>취소</Button>
            <Button onClick={handleReportSubmit} disabled={reportMutation.isPending || !reportReason} className="bg-orange-600 hover:bg-orange-700" data-testid="button-submit-report">
              {reportMutation.isPending ? "접수 중..." : "신고 접수"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={tipOpen} onOpenChange={setTipOpen}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Gift className="text-yellow-500" size={20} /> 아티스트 후원
            </DialogTitle>
            <DialogDescription>
              "{music.title}" - {music.artist}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>후원 금액</Label>
              <div className="flex gap-2 mt-2 flex-wrap">
                {[1000, 3000, 5000, 10000].map((amt) => (
                  <Button
                    key={amt}
                    type="button"
                    variant={tipAmount === amt ? "default" : "outline"}
                    size="sm"
                    onClick={() => setTipAmount(amt)}
                    data-testid={`button-tip-amount-${amt}`}
                  >
                    {amt.toLocaleString()}원
                  </Button>
                ))}
              </div>
              <Input
                type="number"
                min={100}
                step={100}
                value={tipAmount}
                onChange={(e) => setTipAmount(Number(e.target.value))}
                className="mt-2"
                placeholder="직접 입력 (최소 100원)"
                data-testid="input-tip-custom-amount"
              />
            </div>
            <div>
              <Label>응원 메시지 (선택)</Label>
              <Input
                value={tipMessage}
                onChange={(e) => setTipMessage(e.target.value)}
                placeholder="응원 메시지를 남겨보세요"
                className="mt-1"
                data-testid="input-tip-message"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setTipOpen(false)}>취소</Button>
            <Button 
              onClick={() => tipMutation.mutate({ toUserId: music.userId, musicId: music.id, amount: tipAmount, message: tipMessage || undefined })}
              disabled={tipMutation.isPending || tipAmount < 100}
              data-testid="button-confirm-tip"
            >
              {tipMutation.isPending ? "처리 중..." : `${tipAmount.toLocaleString()}원 후원`}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={buyOpen} onOpenChange={setBuyOpen}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Download className="text-green-400" size={20} /> 음원 구매
            </DialogTitle>
            <DialogDescription>
              "{music.title}" - {music.artist}
            </DialogDescription>
          </DialogHeader>
          <div className="text-center py-4">
            <p className="text-3xl font-bold text-foreground">{(music.price || 0).toLocaleString()}원</p>
            <p className="text-sm text-muted-foreground mt-2">구매 후 음원을 다운로드할 수 있습니다</p>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setBuyOpen(false)}>취소</Button>
            <Button 
              onClick={() => purchaseMutation.mutate(music.id)}
              disabled={purchaseMutation.isPending}
              data-testid="button-confirm-purchase"
            >
              {purchaseMutation.isPending ? "처리 중..." : "구매하기"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={playlistOpen} onOpenChange={setPlaylistOpen}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <ListPlus className="text-primary" size={20} /> 플레이리스트에 추가
            </DialogTitle>
            <DialogDescription>
              "{music.title}"을(를) 추가할 플레이리스트를 선택하세요
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-2 max-h-60 overflow-y-auto">
            {playlists && playlists.length > 0 ? (
              playlists.map((pl: any) => (
                <Button
                  key={pl.id}
                  variant="outline"
                  className="w-full justify-start gap-2"
                  disabled={isAddingToPlaylist}
                  onClick={() => {
                    addToPlaylist({ playlistId: pl.id, musicId: music.id }, {
                      onSuccess: () => setPlaylistOpen(false),
                    });
                  }}
                  data-testid={`button-select-playlist-${pl.id}`}
                >
                  <ListPlus size={14} />
                  {pl.name}
                </Button>
              ))
            ) : (
              <p className="text-sm text-muted-foreground text-center py-4">
                플레이리스트가 없습니다. 마이페이지에서 먼저 생성해주세요.
              </p>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setPlaylistOpen(false)}>닫기</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

