        if User.query.filter_by(email=data['email']).first():
            return jsonify({'success': False, 'error': '이미 사용중인 이메일입니다'}), 400
        
        # 사용자 생성
        user = User(
            username=data['username'],
            email=data['email']
        )
        user.set_password(data['password'])  # 비밀번호 해시 저장
        
        db.session.add(user)
        db.session.commit()
        
        return jsonify({
