  });

  const handleWithdraw = () => {
    const amount = Number(withdrawAmount);
    if (!amount || amount < 1000) {
      toast({ title: "오류", description: "최소 출금 금액은 1,000원입니다.", variant: "destructive" });
      return;
    }
    if (!bankName || !accountNumber || !accountHolder) {
      toast({ title: "오류", description: "은행명, 계좌번호, 예금주를 모두 입력해주세요.", variant: "destructive" });
      return;
    }
    withdrawMutation.mutate({ amount, bankName, accountNumber, accountHolder });
  };

  const baseAmount = Number(withdrawAmount || 0);
  const fee = Math.floor(baseAmount * 0.15);
  const vat = Math.floor(fee * 0.1);
  const totalDeduction = fee + vat;
  const netAmount = baseAmount - totalDeduction;

  const statusLabel = (status: string) => {
    switch (status) {
      case "pending": return <Badge variant="secondary"><Clock size={12} className="mr-1" />대기중</Badge>;
      case "approved": return <Badge className="bg-green-500/20 text-green-400"><CheckCircle size={12} className="mr-1" />승인</Badge>;
      case "rejected": return <Badge variant="destructive"><XCircle size={12} className="mr-1" />거부</Badge>;
      default: return <Badge variant="secondary">{status}</Badge>;
    }
  };

  if (isLoadingEarnings) {
    return <div className="flex justify-center py-12"><Loader2 className="animate-spin text-primary" size={24} /></div>;
  }

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Card className="p-5">
          <div className="flex items-center gap-3 flex-wrap">
            <div className="w-10 h-10 rounded-lg bg-primary/20 flex items-center justify-center shrink-0">
              <Wallet className="text-primary" size={20} />
            </div>
            <div>
              <p className="text-sm text-muted-foreground">잔액</p>
              <p className="text-xl font-bold" data-testid="text-balance">{(earnings?.balance || 0).toLocaleString()}원</p>
            </div>
          </div>
        </Card>
        <Card className="p-5">
          <div className="flex items-center gap-3 flex-wrap">
            <div className="w-10 h-10 rounded-lg bg-yellow-500/20 flex items-center justify-center shrink-0">
              <Gift className="text-yellow-500" size={20} />
            </div>
            <div>
              <p className="text-sm text-muted-foreground">총 후원 수익</p>
              <p className="text-xl font-bold" data-testid="text-total-tips">{(earnings?.totalTips || 0).toLocaleString()}원</p>
            </div>
          </div>
        </Card>
        <Card className="p-5">
          <div className="flex items-center gap-3 flex-wrap">
            <div className="w-10 h-10 rounded-lg bg-green-500/20 flex items-center justify-center shrink-0">
              <TrendingUp className="text-green-500" size={20} />
            </div>
            <div>
              <p className="text-sm text-muted-foreground">총 판매 수익</p>
              <p className="text-xl font-bold" data-testid="text-total-sales">{(earnings?.totalSales || 0).toLocaleString()}원</p>
            </div>
          </div>
        </Card>
      </div>

