            <Banknote size={18} className="text-primary" /> 출금
          </h3>
          <Dialog open={withdrawOpen} onOpenChange={setWithdrawOpen}>
            <DialogTrigger asChild>
              <Button size="sm" data-testid="button-withdraw-open">
                <ArrowDownToLine size={14} className="mr-1.5" /> 출금 요청
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>출금 요청</DialogTitle>
