        {isLoadingWithdrawals ? (
          <div className="flex justify-center py-4"><Loader2 className="animate-spin text-primary" size={20} /></div>
        ) : (!withdrawals || withdrawals.length === 0) ? (
          <div className="text-center py-6 text-muted-foreground">
