import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useAuth } from "@/hooks/use-auth";
import { useToast } from "@/hooks/use-toast";
import { Coins, Plus, ArrowDown, ArrowUp, Gift, Download, Loader2, Clock, CreditCard } from "lucide-react";
import { Link } from "wouter";
import { Navigation } from "@/components/Navigation";
import { Footer } from "@/components/Footer";
import { PageTransition } from "@/components/PageTransition";

const CREDIT_PACKAGES = [
  { amount: 1000, label: "1,000", bonus: 0 },
  { amount: 3000, label: "3,000", bonus: 0 },
  { amount: 5000, label: "5,000", bonus: 250, popular: false },
  { amount: 10000, label: "10,000", bonus: 500, popular: true },
  { amount: 30000, label: "30,000", bonus: 2000 },
  { amount: 50000, label: "50,000", bonus: 5000 },
];

export default function Credits() {
  const { user } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [selectedPackage, setSelectedPackage] = useState<number | null>(null);

  const { data: creditData, isLoading } = useQuery<{ credits: number }>({
    queryKey: ["/api/credits"],
    enabled: !!user,
  });

  const { data: transactions, isLoading: isLoadingTx } = useQuery<any[]>({
    queryKey: ["/api/credits/transactions"],
    enabled: !!user,
  });

  const chargeMutation = useMutation({
    mutationFn: async (amount: number) => {
      const res = await fetch("/api/credits/charge", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ amount }),
        credentials: "include",
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.message || "충전 실패");
      }
      return res.json();
    },
    onSuccess: (data) => {
      toast({ title: "충전 완료", description: `크레딧이 충전되었습니다. 현재 잔액: ${data.credits?.toLocaleString()}` });
      queryClient.invalidateQueries({ queryKey: ["/api/credits"] });
      queryClient.invalidateQueries({ queryKey: ["/api/credits/transactions"] });
      queryClient.invalidateQueries({ queryKey: ["/api/earnings"] });
      setSelectedPackage(null);
    },
    onError: (error: Error) => {
      toast({ title: "충전 실패", description: error.message, variant: "destructive" });
    },
  });

  const getTypeLabel = (type: string) => {
    switch (type) {
      case "charge": return "충전";
      case "tip_sent": return "후원";
      case "purchase": return "구매";
      default: return type;
    }
  };

  const getTypeIcon = (type: string) => {
    switch (type) {
      case "charge": return <Plus size={14} className="text-green-400" />;
      case "tip_sent": return <Gift size={14} className="text-yellow-500" />;
      case "purchase": return <Download size={14} className="text-blue-400" />;
      default: return <Coins size={14} />;
    }
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center pb-24">
        <Navigation />
        <Card className="p-8 text-center max-w-sm">
          <Coins className="mx-auto mb-4 text-primary" size={48} />
          <h2 className="text-xl font-bold mb-2">로그인이 필요합니다</h2>
          <p className="text-muted-foreground mb-4">크레딧을 충전하려면 먼저 로그인해주세요</p>
          <Link href="/login">
            <Button data-testid="button-go-login">로그인하기</Button>
          </Link>
        </Card>
        <Footer />
      </div>
    );
  }

  return (
    <PageTransition>
      <div className="min-h-screen bg-background flex flex-col pb-24">
        <Navigation />
        <div className="p-6 max-w-4xl mx-auto">
        <div className="mb-8">
          <h1 className="text-3xl font-bold mb-2" data-testid="text-credits-title">크레딧 충전</h1>
          <p className="text-muted-foreground">크레딧을 충전하여 아티스트를 후원하고 음원을 구매하세요</p>
        </div>

        <Card className="p-6 mb-8">
          <div className="flex items-center justify-between gap-4 flex-wrap">
            <div className="flex items-center gap-4">
              <div className="w-14 h-14 rounded-xl bg-primary/20 flex items-center justify-center">
                <Coins className="text-primary" size={28} />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">내 크레딧</p>
                <p className="text-3xl font-bold" data-testid="text-credit-balance">
                  {isLoading ? <Loader2 className="animate-spin" size={24} /> : (creditData?.credits || 0).toLocaleString()}
                </p>
              </div>
            </div>
            <Badge variant="outline" className="text-sm px-3 py-1">
              1 크레딧 = 1원
            </Badge>
          </div>
        </Card>

        <div className="mb-8">
          <h2 className="text-xl font-semibold mb-4">충전 패키지 선택</h2>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
            {CREDIT_PACKAGES.map((pkg) => (
              <Card
                key={pkg.amount}
                className={`p-5 cursor-pointer transition-all relative ${
                  selectedPackage === pkg.amount
                    ? "ring-2 ring-primary"
                    : "hover-elevate"
                }`}
                onClick={() => setSelectedPackage(pkg.amount)}
                data-testid={`card-package-${pkg.amount}`}
              >
                {pkg.popular && (
                  <Badge className="absolute -top-2 -right-2 bg-primary text-primary-foreground text-xs">
                    인기
                  </Badge>
                )}
                <div className="text-center">
                  <div className="flex items-center justify-center gap-1 mb-2">
                    <Coins size={18} className="text-primary" />
                    <span className="text-2xl font-bold">{pkg.label}</span>
                  </div>
                  <p className="text-sm text-muted-foreground">{pkg.amount.toLocaleString()}원</p>
                  {pkg.bonus > 0 && (
                    <p className="text-xs text-green-400 mt-1">+{pkg.bonus.toLocaleString()} 보너스</p>
                  )}
                </div>
              </Card>
            ))}
          </div>
        </div>

        {selectedPackage && (
          <Card className="p-6 mb-8">
            <div className="flex items-center justify-between gap-4 flex-wrap">
              <div>
                <p className="text-sm text-muted-foreground">선택한 패키지</p>
                <p className="text-xl font-bold">{selectedPackage.toLocaleString()} 크레딧</p>
                {CREDIT_PACKAGES.find(p => p.amount === selectedPackage)?.bonus ? (
                  <p className="text-sm text-green-400">
                    +{CREDIT_PACKAGES.find(p => p.amount === selectedPackage)!.bonus.toLocaleString()} 보너스 크레딧
                  </p>
                ) : null}
              </div>
              <div className="flex gap-2">
                <Button variant="outline" onClick={() => setSelectedPackage(null)}>취소</Button>
                <Button
                  onClick={() => {
                    const pkg = CREDIT_PACKAGES.find(p => p.amount === selectedPackage);
                    const totalAmount = selectedPackage + (pkg?.bonus || 0);
                    chargeMutation.mutate(totalAmount);
                  }}
                  disabled={chargeMutation.isPending}
                  data-testid="button-charge"
                >
                  <CreditCard size={16} className="mr-2" />
                  {chargeMutation.isPending ? "처리 중..." : `${selectedPackage.toLocaleString()}원 결제`}
                </Button>
              </div>
            </div>
            <p className="text-xs text-muted-foreground mt-3">
              * 토스페이먼츠 연동 시 실제 결제가 진행됩니다. 현재는 테스트 모드로 바로 충전됩니다.
            </p>
          </Card>
        )}

        <div>
          <h2 className="text-xl font-semibold mb-4">크레딧 사용 내역</h2>
          {isLoadingTx ? (
            <div className="flex justify-center py-8"><Loader2 className="animate-spin text-primary" size={24} /></div>
          ) : (!transactions || transactions.length === 0) ? (
            <Card className="p-8 text-center">
              <Clock className="mx-auto mb-3 text-muted-foreground opacity-50" size={40} />
              <p className="text-muted-foreground">아직 거래 내역이 없습니다</p>
            </Card>
          ) : (
            <div className="space-y-2">
              {transactions.map((tx: any) => (
                <Card key={tx.id} className="p-4" data-testid={`card-transaction-${tx.id}`}>
                  <div className="flex items-center justify-between gap-2 flex-wrap">
                    <div className="flex items-center gap-3 min-w-0">
                      <div className="w-8 h-8 rounded-lg bg-secondary flex items-center justify-center shrink-0">
                        {getTypeIcon(tx.type)}
                      </div>
                      <div className="min-w-0">
                        <p className="text-sm font-medium">{getTypeLabel(tx.type)}</p>
                        {tx.description && <p className="text-xs text-muted-foreground truncate">{tx.description}</p>}
                      </div>
                    </div>
                    <div className="text-right shrink-0">
                      <p className={`text-sm font-bold ${tx.amount > 0 ? "text-green-400" : "text-red-400"}`}>
                        {tx.amount > 0 ? "+" : ""}{tx.amount.toLocaleString()}
                      </p>
                      <p className="text-xs text-muted-foreground">
                        {tx.createdAt ? new Date(tx.createdAt).toLocaleDateString("ko-KR") : ""}
                      </p>
                    </div>
                  </div>
                </Card>
              ))}
            </div>
          )}
        </div>
      </div>
      <Footer />
      </div>
    </PageTransition>
  );
}

